import { useCallback, useEffect, useState } from 'react'

import type { TodoViewModel } from '../../application/TodoViewModel'
import { useTodosUseCases } from '../useTodosUseCases/useTodosUseCases'

export type TodosState =
  | { readonly status: 'loading' }
  | { readonly status: 'loaded'; readonly todos: TodoViewModel[] }
  | { readonly status: 'failed' }

export type TodosApi = {
  readonly state: TodosState
  readonly notice: string | null
  readonly complete: (id: string) => Promise<void>
}

export const useTodos = (): TodosApi => {
  const { listTodos, completeTodo } = useTodosUseCases()
  const [state, setState] = useState<TodosState>({ status: 'loading' })
  const [notice, setNotice] = useState<string | null>(null)

  useEffect(() => {
    const controller = new AbortController()
    listTodos.execute(controller.signal).then(
      (todos) => setState({ status: 'loaded', todos }),
      () => {
        if (!controller.signal.aborted) setState({ status: 'failed' })
      },
    )
    return () => controller.abort()
  }, [listTodos])

  const complete = useCallback(
    async (id: string) => {
      setNotice(null)
      const result = await completeTodo.execute(id)
      if (result === 'failed') {
        setNotice('The todo could not be completed.')
        return
      }
      if (result === 'already-completed') setNotice('This todo is already completed.')
      setState((current) =>
        current.status === 'loaded'
          ? {
              status: 'loaded',
              todos: current.todos.map((todo) =>
                todo.id === id ? { ...todo, status: 'done' as const } : todo,
              ),
            }
          : current,
      )
    },
    [completeTodo],
  )

  return { state, notice, complete }
}
