import type { TodoGateway } from './TodoGateway'
import { TodoAlreadyCompletedError } from './TodoGateway'

export type CompleteTodoResult = 'completed' | 'already-completed' | 'failed'

export class CompleteTodo {
  private readonly todos: TodoGateway

  constructor(todos: TodoGateway) {
    this.todos = todos
  }

  async execute(id: string): Promise<CompleteTodoResult> {
    try {
      await this.todos.complete(id)
      return 'completed'
    } catch (error) {
      return error instanceof TodoAlreadyCompletedError ? 'already-completed' : 'failed'
    }
  }
}
